const requiresPlanActivation=(organizationId:string)=>{const org=db.prepare('SELECT status,trial_ends_at as trialEndsAt,next_billing_at as nextBillingAt FROM organizations WHERE id=?').get(organizationId) as any;if(!org)return true;if(['Suspended','Cancelled'].includes(org.status))return true;if(hasActiveSaasLicense(organizationId)||hasActiveCommercialSubscription(organizationId))return false;const today=new Date().toISOString().slice(0,10);return desktopTrialExpired()||org.status==='Past due'||(org.status==='Trial'&&(!org.trialEndsAt||org.trialEndsAt<today))||(org.status==='Active'&&org.nextBillingAt&&org.nextBillingAt<today);};
const currentCommercialPlanCode=(organizationId:string)=>{const today=new Date().toISOString().slice(0,10);const subscription=db.prepare("SELECT plan_code as planCode FROM commercial_subscriptions WHERE business_id=? AND subscription_status='ACTIVE' AND start_date<=? AND end_date>=? ORDER BY end_date DESC LIMIT 1").get(organizationId,today,today) as any;if(subscription?.planCode)return subscription.planCode;const trial=db.prepare("SELECT trial_id FROM commercial_trials WHERE business_id=? AND trial_status='ACTIVE' AND trial_start_date<=? AND trial_end_date>=? LIMIT 1").get(organizationId,today,today);if(trial)return 'PRO';const license=db.prepare("SELECT plan_code as planCode,plan FROM saas_licenses WHERE organization_id=? AND status='Active' AND starts_at<=? AND expires_at>=? ORDER BY expires_at DESC LIMIT 1").get(organizationId,today,today) as any;if(license)return normalizePlanCode(license.planCode||license.plan);const org=db.prepare('SELECT plan,status FROM organizations WHERE id=?').get(organizationId) as any;return normalizePlanCode(org?.plan||'STARTER');};
