const planLimitFailure=(organizationId:string,resource:'properties'|'beds'|'users',adding:number)=>{const code=currentCommercialPlanCode(organizationId),plan=commercialPlan(code);if(!plan)return null;const config={properties:{limit:Number(plan.maxProperties),label:'property',table:'properties'},beds:{limit:Number(plan.maxBeds),label:'bed',table:'beds'},users:{limit:Number(plan.maxUsers),label:'user account',table:'users'}}[resource];if(config.limit<0)return null;const current=Number((db.prepare(`SELECT COUNT(*) as count FROM ${config.table} WHERE organization_id=?`).get(organizationId) as any)?.count||0);if(current+adding<=config.limit)return null;const next={STARTER:'PRO',PRO:'BUSINESS',DESKTOP:'PRO'}[code];const nextPlan=next?commercialPlan(next):null;const nextLimit=nextPlan?Number(nextPlan[resource==='properties'?'maxProperties':resource==='beds'?'maxBeds':'maxUsers']):0;return {error:`You've reached the ${config.limit}-${config.label} limit of the ${plan.name} plan.${next?` Upgrade to ${next} to manage up to ${nextLimit} ${config.label}s.`:''}`,code:'PLAN_LIMIT',planCode:code,limit:config.limit,used:current,upgradePlan:next||null,upgradeLimit:nextLimit};};
