  try{integrity=check.pragma('integrity_check',{simple:true}) as string;belongsToOrg=!!check.prepare('SELECT 1 FROM organizations WHERE id=?').get(orgId);hasOtherOrganizations=!!check.prepare('SELECT 1 FROM organizations WHERE id<>? LIMIT 1').get(orgId);}finally{check.close();}
