 const b=req.body||{},u=userFor(req),propertyId=val(b.propertyId,100),meterType=val(b.meterType,20),year=Math.round(Number(b.year)),month=Math.round(Number(b.month)),reading=Number(b.reading),commonReading=Number(b.commonReading),floorName=val(b.floorName,100),readingDate=val(b.readingDate,10),readingMode=val(b.readingMode,20)||'direct',property=db.prepare('SELECT id FROM properties WHERE id=? AND organization_id=?').get(propertyId,u.organizationId);
