 if(!['Main meter','Sub meter'].includes(meterType)||!['readings','direct'].includes(readingMode)||!Number.isInteger(year)||year<2000||year>2200||!Number.isInteger(month)||month<1||month>12||!/^\d{4}-\d{2}-\d{2}$/.test(readingDate)||Number.isNaN(Date.parse(`${readingDate}T00:00:00Z`))||new Date(`${readingDate}T00:00:00Z`).toISOString().slice(0,10)!==readingDate)return res.status(400).json({error:'Choose a valid meter type, entry method, month and year, and reading date.'});
