const publicLeadWindows=new Map<string,{start:number;count:number}>();
const slugify=(s:string)=>s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,90)||'pg';
const publicListingSelect=`SELECT l.property_id as propertyId,l.slug,l.title,l.description,l.city,l.area,l.public_address as publicAddress,l.gender,l.amenities_json as amenitiesJson,l.house_rules as houseRules,l.photos_json as photosJson,l.monthly_rent as monthlyRent,l.security_deposit as securityDeposit,l.public_phone as publicPhone,l.featured,p.name as propertyName,p.type,p.beds,p.created_at as propertyCreatedAt FROM public_property_listings l JOIN properties p ON p.id=l.property_id`;
app.get('/api/public/stay',(req,res)=>{const city=val(req.query.city,100).toLowerCase(),query=val(req.query.q,120).toLowerCase(),gender=val(req.query.gender,20),budget=Number(req.query.budget)||0;const rows=db.prepare(`${publicListingSelect} WHERE l.published=1 AND (?='' OR lower(l.city)=? OR lower(l.area)=?) AND (?='' OR lower(l.title) LIKE ? OR lower(l.area) LIKE ? OR lower(l.city) LIKE ? OR lower(l.public_address) LIKE ?) AND (?='' OR l.gender=? OR l.gender='Unisex') AND (?=0 OR l.monthly_rent<=?) ORDER BY l.featured DESC,l.updated_at DESC`).all(city,city,city,query,`%${query}%`,`%${query}%`,`%${query}%`,`%${query}%`,gender,gender,budget,budget) as any[];const listings=rows.map(x=>{x.amenities=JSON.parse(x.amenitiesJson||'[]');x.photos=JSON.parse(x.photosJson||'[]');x.roomTypes=(db.prepare('SELECT DISTINCT type FROM rooms WHERE property_id=? ORDER BY type').all(x.propertyId) as any[]).map(r=>r.type);delete x.amenitiesJson;delete x.photosJson;x.availableBeds=Math.max(0,Number(x.beds||0)-Number((db.prepare("SELECT COUNT(*) as n FROM residents WHERE organization_id=(SELECT organization_id FROM properties WHERE id=?) AND property_id=? AND occupancy_status='Active'").get(x.propertyId,x.propertyId) as any)?.n||0));x.availableRooms=Number((db.prepare('SELECT COUNT(*) as n FROM rooms WHERE property_id=? AND organization_id=(SELECT organization_id FROM properties WHERE id=?)').get(x.propertyId,x.propertyId) as any)?.n||0);delete x.publicPhone;return x;});res.json({listings,cities:(db.prepare('SELECT DISTINCT city FROM public_property_listings WHERE published=1 AND city<>\'\' ORDER BY city').all() as any[]).map(x=>x.city)});});
