app.post('/api/public/stay/:slug/book',(req,res)=>{const ip=String(req.ip||req.socket.remoteAddress||'unknown'),now=Date.now(),bucket=publicLeadWindows.get(ip);if(bucket&&now-bucket.start<60_000&&bucket.count>=8)return res.status(429).json({error:'Too many requests. Please try again in a minute.'});if(!bucket||now-bucket.start>=60_000)publicLeadWindows.set(ip,{start:now,count:1});else bucket.count++;const listing=db.prepare(`${publicListingSelect} WHERE l.published=1 AND l.slug=?`).get(req.params.slug) as any;if(!listing)return res.status(404).json({error:'This property listing is unavailable.'});const b=req.body||{},name=val(b.name,120),phone=val(b.phone,30).replace(/[^+\d]/g,'');if(name.length<2||phone.replace(/\D/g,'').length<10)return res.status(400).json({error:'Enter your name and a valid mobile number.'});const id=uid(),created=nowIso(),sequence=Number((db.prepare("SELECT COUNT(*) as n FROM booking_leads WHERE created_at>=?").get(`${new Date().getFullYear()}-01-01`) as any).n||0)+1,bookingNo=`ABR-${new Date().getFullYear()}-${String(sequence).padStart(6,'0')}`;db.prepare(`INSERT INTO booking_leads (id,booking_no,organization_id,property_id,customer_name,phone,email,gender,occupation,occupants,room_preference,move_in,duration,budget,notes,status,created_at,updated_at) SELECT ?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'NEW',?,? WHERE EXISTS(SELECT 1 FROM public_property_listings WHERE property_id=? AND published=1)`).run(id,bookingNo,db.prepare('SELECT organization_id FROM properties WHERE id=?').pluck().get(listing.propertyId),listing.propertyId,name,phone,val(b.email,180),val(b.gender,30),val(b.occupation,100),Math.min(20,Math.max(1,Number(b.occupants)||1)),val(b.roomPreference,100),val(b.moveIn,20),val(b.duration,60),Math.max(0,Number(b.budget)||0),val(b.notes,1000),created,created,listing.propertyId);res.status(201).json({bookingNo,status:'NEW',message:'Your request has been sent to the property. The owner will contact you to confirm availability.'});});

const requireNetworkFeature=(feature:string)=>(req:express.Request,res:express.Response,next:express.NextFunction)=>{const u=userFor(req);if(!u)return res.status(401).json({error:'Please sign in to continue.'});if(!canUseFeature(u.organizationId,feature))return res.status(403).json({error:`This feature is not enabled for your plan. Contact your administrator to enable ${feature.replaceAll('_',' ')}.`,code:'PLAN_FEATURE_REQUIRED',feature});next();};
