const dist=path.join(root,'dist');let hasBuiltUi=false;try{await fs.access(path.join(dist,'index.html'));hasBuiltUi=true;}catch(error){console.error('Built UI is unavailable:',error instanceof Error?error.message:'unknown error');}if(hasBuiltUi){app.use(express.static(dist));app.get('/platform',(_req,res)=>res.sendFile(path.join(dist,'index.html')));app.use((req,res,next)=>{if(req.method!=='GET'||req.path.startsWith('/api/'))return next();res.sendFile(path.join(dist,'index.html'));});}
const port=Number(process.env.PORT)||3000;const host=process.env.HOST||'127.0.0.1';const httpServer=app.listen(port,host,()=>console.log(`Autrob PG Manager service listening on ${host}:${port}`));httpServer.ref();const serviceKeepAlive=setInterval(()=>{if(!httpServer.listening)httpServer.listen(port,host)},30_000);serviceKeepAlive.ref();const stopService=()=>{clearInterval(serviceKeepAlive);httpServer.close()};process.once('SIGINT',stopService);process.once('SIGTERM',stopService);

